nsa = value["NumberOfAverages"].dropna()
if len(nsa) > 0:
    manufacturer = value["Manufacturer"].iloc[0].upper() if "Manufacturer" in value.columns and not value["Manufacturer"].isna().all() else ""

    # Get unique NSA values
    nsa_values = sorted(nsa.unique())
    min_nsa = min(nsa_values)
    max_nsa = max(nsa_values)

    if "PHILIPS" in manufacturer:
        # Philips: 3 for low b, 10 for high b
        if max_nsa < 8:
            raise ValidationWarning(f"Philips DWI typically uses NSA=10 for high b-value images. Found max NSA={max_nsa}")
        elif len(nsa_values) == 1 and nsa_values[0] == 10:
            raise ValidationWarning(f"Philips DWI typically uses lower NSA (3) for low b-value images to save time. All images have NSA={nsa_values[0]}")
    elif "SIEMENS" in manufacturer:
        # Siemens: 4-5 for high b
        if max_nsa < 4 or max_nsa > 6:
            raise ValidationWarning(f"Siemens DWI typically uses NSA=4-5 for high b-value images. Found max NSA={max_nsa}")
    elif "GE" in manufacturer or "GENERAL ELECTRIC" in manufacturer:
        # GE: 4 for high b
        if max_nsa < 3 or max_nsa > 5:
            raise ValidationWarning(f"GE DWI typically uses NSA=4 for high b-value images. Found max NSA={max_nsa}")
    else:
        # Unknown vendor - check reasonable range
        if min_nsa < 2 or max_nsa > 12:
            raise ValidationWarning(f"NumberOfAverages ({min_nsa}-{max_nsa}) outside typical range (3-10) for WB-DWI.")
